Lemma rw_C8_of_stk : forall (m : mem) lo hi a, stk asegs m lo hi -> lo <= a -> a + 8 <= hi -> exists w, rw_cells asegs m a [C8 w].
Proof.
  intros m lo hi a S H1 H2. destruct (stk_split asegs m lo a hi S ltac:(lia)) as [_ S2].
  destruct (stk_split asegs m a (a + 8) hi S2 ltac:(lia)) as [S3 _].
  destruct (stk_CB m a 8 S3 ltac:(lia)) as (bs & Hb). destruct (word_of_stk m a (a + 8) a S3 ltac:(lia) ltac:(lia)) as (v & Hv).
  exists v. split; [exact Hv | exact (proj2 Hb)].
Qed.

